                hello_frame = ev
            if frame == 'HelloAck' and hello_frame is not None:
                if (ev.get('capabilities') != hello_frame.get('expectedCapabilities')
                        or ev.get('identityVersions') != hello_frame.get('identityVersions')):
                    state['phase'] = 'FAULT'
                    trace.append({'frame': frame, 'rule': 'payload:hello-ack-echo-mismatch(s9.1-step2)',
                                  'phase': 'FAULT'})
                    continue
            row = self._match(state, frame)
            if row is None:
                state['phase'] = 'FAULT'
                trace.append({'frame': frame, 'rule': 'P3-34', 'phase': 'FAULT'})
                continue
            self._updates(state, ev)
            nxt = row['next']
            if nxt == 'ANALYZING_OR_READY_COMPLETE':
                state['stageIndex'] += 1
                state['stagesCompleted'] += 1
                nxt = 'READY_COMPLETE' if state['stageIndex'] == state['stageCount'] else 'ANALYZING'
            if 'terminal' in row:
                state['terminalKind'] = row['terminal']
            state['phase'] = nxt
            trace.append({'frame': frame, 'rule': row['id'], 'phase': nxt})
        return {'state': state, 'trace': trace}

    def _match(self, state, frame):
        for row in self.rules:
            if row['phase'] == '*ANY':
                continue
            if row['phase'] == '*PRE_COMPLETE':
                if state['phase'] not in self.pre_complete:
                    continue
            elif row['phase'] != state['phase']:
                continue
            if row['frame'] != frame:
                continue
            if all(state.get(k) == v for k, v in row.get('guard', {}).items()):
                return row
        return None

    def _updates(self, state, ev):
        frame = ev['frame']
        if frame == 'HelloAck':
            caps = ev.get('capabilities') or []
            state['identityNegotiated'] = all(tok in caps for tok in IDENTITY_TOKENS)
        if frame == 'OpenUniverse':
            state['dependencyMode'] = bool(ev.get('dependencyMode'))
            state['preparedMode'] = bool(ev.get('preparedMode'))
        if frame == 'Analyze':
            state['stageCount'] = ev['stageCount']
            state['stageIndex'] = 0
        if frame in ('DependencySourceChunk', 'DependencySourceManifest', 'OpenUniverse',
                     'PreparedOutputChunk', 'PreparedOutputManifest', 'SnapshotFileChunk', 'SnapshotManifest'):
            state['sourceBytesSent'] = True

    def pairwise_disjoint(self):
        """Control: no two non-wildcard rows can match one (phase, frame, state)."""
        overlaps = []
        rows = [r for r in self.rules if r['phase'] != '*ANY']
        for i, a in enumerate(rows):
            for b in rows[i + 1:]:
                pa = self.pre_complete if a['phase'] == '*PRE_COMPLETE' else {a['phase']}
                pb = self.pre_complete if b['phase'] == '*PRE_COMPLETE' else {b['phase']}
                if not (pa & pb) or a['frame'] != b['frame']:
                    continue
                ga, gb = a.get('guard', {}), b.get('guard', {})
                if any(k in gb and gb[k] != v for k, v in ga.items()):
                    continue
                overlaps.append((a['id'], b['id']))
        return overlaps


# native-evidence.md section 10 fault law / StageAuthorityV1 projection of a terminal kind.
def stage_authority(terminal_kind, faulted):
    if faulted:
        return {"terminalKind": "fault", "factsAdmitted": "none", "coverageEntriesAdmitted": False,
                "runMayBeSealed": False, "authority": "none", "diagnosticsCarrier": "operational-record-only",
                "d9": {"class": "operational-failed", "exitCode": 4, "code": "PROVIDER.PROTOCOL_VIOLATION"}}
    if terminal_kind == 'complete':
        return {"terminalKind": "complete", "factsAdmitted": "all", "coverageEntriesAdmitted": True,
                "runMayBeSealed": True, "authority": "authoritative", "diagnosticsCarrier": "operational-record-only",
                "d9": {"class": "success", "exitCode": 0, "code": None}}
    if terminal_kind in ('unavailable', 'budget-exhausted'):
        code = 'COVERAGE.PROVIDER_UNAVAILABLE' if terminal_kind == 'unavailable' else 'COVERAGE.BUDGET_EXHAUSTED'
        return {"terminalKind": terminal_kind, "factsAdmitted": "before-terminal", "coverageEntriesAdmitted": True,
                "runMayBeSealed": True, "authority": "authoritative", "diagnosticsCarrier": "operational-record-only",
                "d9": {"class": "indeterminate", "exitCode": 3, "code": code}}
    if terminal_kind == 'cancelled':
        return {"terminalKind": "cancelled", "factsAdmitted": "none", "coverageEntriesAdmitted": False,
                "runMayBeSealed": False, "authority": "none", "diagnosticsCarrier": "operational-record-only",
                "d9": {"class": "interrupted", "exitCode": 130, "code": None}}
    if terminal_kind == 'provider-fault':
        return {"terminalKind": "provider-fault", "factsAdmitted": "none", "coverageEntriesAdmitted": False,
                "runMayBeSealed": False, "authority": "none", "diagnosticsCarrier": "operational-record-only",
                "d9": {"class": "operational-failed", "exitCode": 4, "code": "PROVIDER.PROTOCOL_VIOLATION"}}
    raise ValueError(terminal_kind)

"""Portable glob matching v1 (docs/coop/design-corrections/foundation/glob-pattern-contract.v1.md)."""


def _segment_match(pat, cand):
    # '*' zero or more scalars within a segment, '?' exactly one scalar; everything else literal.
    p, c = list(pat), list(cand)
    memo = {}

    def m(i, j):
        key = (i, j)
        if key in memo:
            return memo[key]
        if i == len(p):
            r = j == len(c)
        elif p[i] == '*':
            r = m(i + 1, j) or (j < len(c) and m(i, j + 1))
        elif p[i] == '?':
            r = j < len(c) and m(i + 1, j + 1)
        else:
            r = j < len(c) and p[i] == c[j] and m(i + 1, j + 1)
        memo[key] = r
        return r

    return m(0, 0)


def glob_match(pattern, candidate):
    P = pattern.split('/')
    S = candidate.split('/')
    memo = {}

    def m(i, j):
        key = (i, j)
        if key in memo:
            return memo[key]
        if i == len(P):
            r = j == len(S)
        elif P[i] == '**':
            r = any(m(i + 1, k) for k in range(j, len(S) + 1))
        else:
            r = j < len(S) and _segment_match(P[i], S[j]) and m(i + 1, j + 1)
        memo[key] = r
        return r

    return m(0, 0)


def scope_document_selects(scope_doc, path):
    """ScopeDocumentV1: at least one include matches and no exclude matches (exclusion wins)."""
    if not any(glob_match(p, path) for p in scope_doc['include']):
        return False
    return not any(glob_match(p, path) for p in scope_doc.get('exclude', []))


def rule_enumeration_selects(include, exclude, path):
    """Composition section 2: include absent or [] means all paths; exclusion wins."""
    inc = include or []
    if inc and not any(glob_match(p, path) for p in inc):
        return False
    return not any(glob_match(p, path) for p in (exclude or []))

"""Kit schema admission: stock Draft 2020-12 validation PLUS the published kit keywords.

Layers (kept distinct and reported separately):
  1. exact typed admission of the already-parsed value (canonical.check_typed): bool is not an
     integer, float is never an integer (stock jsonschema admits 1.0 for const/enum 1);
  2. stock JSON Schema validation through a local registry of the exact kit documents
     (no network; $ref resolved by $id / kit path);
  3. x-opensip-order: the closed identity section 3 vocabulary, enforced over every array the
     schema walk reaches (including allOf/if-then/oneOf branches that apply);
  4. x-opensip-digest scope check on bare 64-hex fields (reported per selector).
Relation/digest-domain/registry laws are separate modules (closure.py) and are NOT claimed here.
"""
import hashlib
import json
import os
from urllib.parse import urljoin

import jsonschema
from jsonschema import Draft202012Validator
import referencing
from referencing import Registry, Resource
from referencing.jsonschema import DRAFT202012

from canonical import check_typed, C, AdmissionError

KIT_DOCS = '/private/tmp/opensip-design-corrections/consumer-b.v24/subject/docs/'
DC = 'coop/design-corrections/'
ORDER_VOCAB = {"sequence", "canonical-set", "canonical-order", "utf8", "path", "numeric", "ordinal",
               "predicate", "ruleId", "waiverId"}
HEX64 = "^[0-9a-f]{64}(?![\\s\\S])"


def norm_rel(rel):
    if rel.startswith('docs/'):
        rel = rel[5:]
    if not rel.startswith('coop/') and not rel.startswith('v2/'):
        rel = DC + rel
    return rel


class Kit:
    def __init__(self):
        self.docs = {}
        self.raw = {}
        self.uri_of = {}
        resources = []
        for d, _, fs in os.walk(KIT_DOCS):
            for f in fs:
                if not f.endswith('.json'):
                    continue
                p = os.path.join(d, f)
                rel = os.path.relpath(p, KIT_DOCS)
                b = open(p, 'rb').read()
                doc = json.loads(b)
                self.raw[rel] = b
                self.docs[rel] = doc
                kit_uri = 'kit:///' + rel
                uris = {kit_uri}
                if isinstance(doc, dict) and isinstance(doc.get('$id'), str):
                    uris.add(doc['$id'])
                    uris.add(urljoin(kit_uri, doc['$id']))
                self.uri_of[rel] = doc.get('$id', kit_uri) if isinstance(doc, dict) else kit_uri
                res = Resource.from_contents(doc, default_specification=DRAFT202012)
                for u in uris:
                    resources.append((u, res))
        self.registry = Registry().with_resources(resources)

    def digest(self, rel):
        return hashlib.sha256(self.raw[norm_rel(rel)]).hexdigest()

    def doc(self, rel):
        return self.docs[norm_rel(rel)]

    def base_uri(self, rel):
        rel = norm_rel(rel)
        doc = self.docs[rel]
        return doc.get('$id') if isinstance(doc, dict) and isinstance(doc.get('$id'), str) else 'kit:///' + rel

    def resolve_pointer(self, rel, selector):
        doc = self.doc(rel)
        cur = doc
        if selector in ('#', ''):
            return cur
        for tok in selector.lstrip('#').lstrip('/').split('/'):
            tok = tok.replace('~1', '/').replace('~0', '~')
            cur = cur[int(tok)] if isinstance(cur, list) else cur[tok]
        return cur

    # -------------------------------------------------------------- validation
    def validator_for(self, rel, selector):
        base = self.base_uri(rel)
        ref = base + ('#' + selector.lstrip('#') if selector not in ('#', '') else '')
        schema = {"$schema": "https://json-schema.org/draft/2020-12/schema", "$ref": ref}
        return Draft202012Validator(schema, registry=self.registry), ref

    def stock_errors(self, instance, rel, selector):
        v, _ = self.validator_for(rel, selector)
        errs = sorted(v.iter_errors(instance), key=lambda e: list(e.absolute_path))
        return [{"path": "/" + "/".join(str(x) for x in e.absolute_path), "message": e.message[:300],
                 "keyword": e.validator} for e in errs]

    def admit(self, instance, rel, selector):
        """Full kit-schema admission of one record. Returns {'ok', 'typed', 'stock', 'order'}."""
        out = {"document": norm_rel(rel), "selector": selector, "typed": None, "stock": [], "order": []}
        try:
            check_typed(instance)
        except AdmissionError as exc:
            out["typed"] = exc.boundary + (":" + exc.detail if exc.detail else "")
        out["stock"] = self.stock_errors(instance, rel, selector)
        if not out["stock"]:
            out["order"] = self.order_violations(instance, rel, selector)
        out["ok"] = out["typed"] is None and not out["stock"] and not out["order"]
        return out

    # -------------------------------------------------------------- x-opensip-order walk
    def order_violations(self, instance, rel, selector):
        base = self.base_uri(rel)
        resolver = self.registry.resolver(base_uri=base)
        start = self.resolve_pointer(rel, selector)
        viol = []
        self._walk(start, instance, resolver, "$", viol, depth=0)
        # de-duplicate (the same array may be reached by several schema paths)
        seen, out = set(), []
        for x in viol:
            key = json.dumps(x, sort_keys=True)
            if key not in seen:
                seen.add(key)
                out.append(x)
        return out

    def _is_valid(self, schema, instance, resolver):
        try:
            v = Draft202012Validator(schema, registry=self.registry, _resolver=resolver)
        except TypeError:
            v = Draft202012Validator(schema, registry=self.registry)
        return v.is_valid(instance)

    def _walk(self, schema, inst, resolver, path, viol, depth):
        if depth > 200 or not isinstance(schema, dict):
            return
        if '$ref' in schema:
            resolved = resolver.lookup(schema['$ref'])
            self._walk(resolved.contents, inst, resolved.resolver, path, viol, depth + 1)
        for key in ('allOf',):
            for sub in schema.get(key, []):
                self._walk(sub, inst, resolver, path, viol, depth + 1)
        for key in ('anyOf', 'oneOf'):
            for sub in schema.get(key, []):
                if self._is_valid(sub, inst, resolver):
                    self._walk(sub, inst, resolver, path, viol, depth + 1)
        if 'if' in schema:
            if self._is_valid(schema['if'], inst, resolver):
                if 'then' in schema:
                    self._walk(schema['then'], inst, resolver, path, viol, depth + 1)
            elif 'else' in schema:
                self._walk(schema['else'], inst, resolver, path, viol, depth + 1)
        if isinstance(inst, list):
            if 'x-opensip-order' in schema:
                self._check_order(schema['x-opensip-order'], inst, path, viol)
            if isinstance(schema.get('items'), dict):
                for i, item in enumerate(inst):
                    self._walk(schema['items'], item, resolver, f"{path}[{i}]", viol, depth + 1)
            for i, sub in enumerate(schema.get('prefixItems', [])):
                if i < len(inst):
                    self._walk(sub, inst[i], resolver, f"{path}[{i}]", viol, depth + 1)
        if isinstance(inst, dict):
            props = schema.get('properties', {})
            for k, v in inst.items():
                if k in props:
                    self._walk(props[k], v, resolver, f"{path}.{k}", viol, depth + 1)
                elif isinstance(schema.get('additionalProperties'), dict):
                    self._walk(schema['additionalProperties'], v, resolver, f"{path}.{k}", viol, depth + 1)

    @staticmethod
    def _key_bytes(item, key):
        v = item.get(key) if isinstance(item, dict) else None
        if isinstance(v, str):
            return v.encode('utf-8')
        if type(v) is int:
            return v
        return None

    def _check_order(self, ann, arr, path, viol):
        def refuse(reason):
            viol.append({"path": path, "order": ann, "violation": reason})

        if isinstance(ann, dict):
            if set(ann.keys()) != {"by"} or not isinstance(ann["by"], list) or not ann["by"]:
                return refuse("ORDER_ANNOTATION_UNKNOWN")
            keys = []
            for it in arr:
                tup = []
                for k in ann["by"]:
                    kb = self._key_bytes(it, k)
                    if kb is None:
                        return refuse(f"ORDER_KEY_MISSING:{k}")
                    tup.append(kb)
                keys.append(tuple(tup))
            for i in range(1, len(keys)):
                if keys[i - 1] >= keys[i]:
                    return refuse(f"ORDER_OR_DUPLICATE_AT:{i}")
            return
        if ann not in ORDER_VOCAB:
            return refuse("ORDER_ANNOTATION_UNKNOWN")
        if ann == 'sequence':
            return
        if ann in ('canonical-set', 'canonical-order'):
            enc = [C(x) for x in arr]
            for i in range(1, len(enc)):
                if ann == 'canonical-set' and enc[i - 1] >= enc[i]:
                    return refuse(f"ORDER_OR_DUPLICATE_AT:{i}")
                if ann == 'canonical-order' and enc[i - 1] > enc[i]:
                    return refuse(f"ORDER_DECREASING_AT:{i}")
            return
        if ann == 'utf8':
            if not all(isinstance(x, str) for x in arr):
                return refuse("ORDER_UTF8_NON_STRING")
            b = [x.encode('utf-8') for x in arr]
        elif ann == 'numeric':
            if not all(type(x) is int for x in arr):
                return refuse("ORDER_NUMERIC_NON_INTEGER")
            b = arr
        elif ann == 'ordinal':
            for i, it in enumerate(arr):
                if not isinstance(it, dict) or type(it.get('ordinal')) is not int or it['ordinal'] != i:
                    return refuse(f"ORDER_ORDINAL_NOT_CONTIGUOUS_AT:{i}")
            return
        elif ann == 'path':
            b = [self._key_bytes(it, 'path') for it in arr]
        elif ann in ('ruleId', 'waiverId'):
            b = [self._key_bytes(it, ann) for it in arr]
        elif ann == 'predicate':
            b = []
            for it in arr:
                t = tuple(self._key_bytes(it, k) for k in ('ruleId', 'subjectId', 'predicateId'))
                if None in t:
                    return refuse("ORDER_KEY_MISSING:predicate")
                b.append(t)
        if any(x is None for x in b):
            return refuse(f"ORDER_KEY_MISSING:{ann}")
        for i in range(1, len(b)):
            if b[i - 1] >= b[i]:
                return refuse(f"ORDER_OR_DUPLICATE_AT:{i}")

    # -------------------------------------------------------------- digest annotation census
    def unannotated_hex_fields(self, rel):
        """Mechanical scan of a schema document: properties whose schema is (or $refs a def that is)
        the bare 64-hex pattern without an x-opensip-digest annotation on the property or its
        nullable branch. Reported, not silently tolerated."""
        doc = self.doc(rel)
        out = []

        def is_hex(s, seen):
            if not isinstance(s, dict):
                return False
            if s.get('pattern') == HEX64:
                return True
            r = s.get('$ref')
            if isinstance(r, str) and r.startswith('#/$defs/') and r not in seen:
                tgt = doc.get('$defs', {}).get(r.split('/')[-1])
                return is_hex(tgt, seen | {r})
            return False

        def annotated(s):
            if not isinstance(s, dict):
                return False
            if 'x-opensip-digest' in s:
                return True
            for alt in s.get('oneOf', []) + s.get('anyOf', []):
                if isinstance(alt, dict) and 'x-opensip-digest' in alt:
                    return True
            return False

        def walk(s, p):
            if isinstance(s, dict):
                for k, v in s.get('properties', {}).items():
                    cand = [v] + [a for a in (v.get('oneOf', []) + v.get('anyOf', [])) if isinstance(a, dict)] if isinstance(v, dict) else []
                    if any(is_hex(c, set()) for c in cand) and not annotated(v):
                        out.append(f"{p}/properties/{k}")
                    walk(v, f"{p}/properties/{k}")
                for key in ('items', 'additionalProperties'):
                    if isinstance(s.get(key), dict):
                        it = s[key]
                        if is_hex(it, set()) and not annotated(it):
                            out.append(f"{p}/{key}")
                        walk(it, f"{p}/{key}")
                for key in ('allOf', 'oneOf', 'anyOf'):
                    for i, sub in enumerate(s.get(key, [])):
                        walk(sub, f"{p}/{key}/{i}")
                for key in ('then', 'else', 'if'):
                    if isinstance(s.get(key), dict):
                        walk(s[key], f"{p}/{key}")
                for name, d in s.get('$defs', {}).items():
                    walk(d, f"{p}/$defs/{name}")

        walk(doc, '#')
        return out


_KIT = None


def kit():
    global _KIT
    if _KIT is None:
        _KIT = Kit()
    return _KIT

