EXCLUDE_REASONS = {"host-ignore-convention", "nested-repository", "nested-project", "custody-excluded"}


def cell_state(capability, mode):
    return next(c for c in MATRIX["cells"] if c["capability"] == capability and c["mode"] == mode)


def subject_language(path):
    best, lang = None, "unspecified"
    for m in LANG_TABLE["members"]:
        for s in m["suffixes"]:
            if path.endswith(s) and (best is None or len(s) > len(best)):
                best, lang = s, m["languageId"]
    return lang


def root_internal(ws):
    return "" if ws == "." else ws


def file_extent(membership, scope, workspace_root):
    root = root_internal(workspace_root)
    out = []
    for row in membership["rows"]:
        if row["membership"] == "outside-project-boundary" or row["reason"] in EXCLUDE_REASONS:
            continue
        if not M.under(row["path"], root):
            continue
        if not M.in_foundation_scope(row["path"], scope):
            continue
        out.append(row["path"])
    return sorted(out, key=lambda p: K.C(p))


def named_manifests(inv_bytes, paths):
    """(named rows, failed paths) for first-party package manifests among paths."""
    named, failed = [], []
    for p in paths:
        base = p.split("/")[-1]
        if base not in ("package.json", "Cargo.toml"):
            continue
        try:
            if base == "package.json":
                data = K.parse_raw(inv_bytes[p])
                name = data.get("name") if isinstance(data, dict) else None
                version = data.get("version", "0.0.0") if isinstance(data, dict) else None
                if name is None:
                    continue
                if not isinstance(name, str) or not name:
                    failed.append(p)
                    continue
            else:
                data = tomllib.loads(inv_bytes[p].decode("utf-8"))
                pkg = data.get("package")
                if pkg is None:
                    continue
                name = pkg.get("name") if isinstance(pkg, dict) else None
                version = pkg.get("version", "0.0.0") if isinstance(pkg, dict) else None
                if not isinstance(name, str) or not name:
                    failed.append(p)
                    continue
            named.append({"path": p, "name": name, "version": version})
        except Exception:
            failed.append(p)
    return named, failed


def symbol_extent(bound, file_paths, membership):
    dom = bound["domain"]
    if dom == "native.semantic-universe.syntax.v2":
        ctx = bound["contextAdmission"]["context"]
        sel = set(bound["universe"]["selectedGrammarIds"])
        sufs = [s for g in ctx["grammarBundle"]["grammars"] if g["grammarId"] in sel and g["syntaxClass"] == "code" for s in g["suffixes"]]
        return sorted([p for p in file_paths if suffix_select(sufs, p) is not None], key=lambda p: K.C(p))
    if dom == "native.semantic-universe.typescript.v2":
        roots = set(bound["universe"]["programRootFiles"])
        return sorted([p for p in file_paths if p in roots], key=lambda p: K.C(p))
    own = bound["sourceUnitOwnership"]
    if own is None:
        return []
    sel = set(own["selectedUnitIds"])
    paths = {o["path"] for o in own["ownership"] if o["unitId"] in sel}
    return sorted([p for p in file_paths if p in paths], key=lambda p: K.C(p))


def admit_enumeration(plan, plan_id, analysis_spec, scope, membership_rec, enum_plan, inventories, bound_by_hex, closures, inv_bytes):
    """Returns (faults, index). index: {(cellOrdinal, programOrdinal, kind): (digest, inventory)} plus derived extents."""
    faults = []
    r = KIT.admit(enum_plan, ENUM_DOC, "#")
    if not r["ok"]:
        return [f"ENUMERATION_PLAN_SCHEMA:{r['stock'][:1]}{r['order'][:1]}"], None
    if enum_plan["snapshotId"] != plan["snapshotId"]:
        faults.append("ENUMERATION_PLAN_SNAPSHOT_MISMATCH")
    if enum_plan["scopeDigest"] != plan["scopeDigest"] or K.raw_digest(scope) != plan["scopeDigest"]:
        faults.append("ENUMERATION_PLAN_SCOPE_DIGEST_MISMATCH")
    mr = KIT.admit(membership_rec, NE, "#/$defs/UnitMembershipV1")
    if not mr["ok"]:
        faults.append("ENUMERATION_MEMBERSHIP_SCHEMA")
    if enum_plan["membershipDigest"] != K.raw_digest(membership_rec):
        faults.append("ENUMERATION_PLAN_MEMBERSHIP_DIGEST_MISMATCH")
    req = {(c["capabilityId"], c["languageMode"], c["workspaceRoot"], c["required"]) for c in analysis_spec["requestedCapabilities"]}
    cells = {(c["capabilityId"], c["languageMode"], c["workspaceRoot"], c["required"]) for c in enum_plan["cells"]}
    if req != cells or len(enum_plan["cells"]) != len(analysis_spec["requestedCapabilities"]):
        faults.append("ENUMERATION_PLAN_CELL_TUPLE_MISMATCH")
    index = {"inventories": {}, "extents": {}, "cells": enum_plan["cells"]}
    semantic = set(plan["semanticClosures"])
    for ci, cell in enumerate(enum_plan["cells"]):
        if sorted(cell["kinds"]) != sorted(KIND_DERIVATION[cell["capabilityId"]]):
            faults.append(f"ENUMERATION_PLAN_KIND_DERIVATION:{ci}")
        if cell_state(cell["capabilityId"], cell["languageMode"])["state"] == "NOT-SELECTED":
            faults.append(f"native.requested-capability-mode-not-selected:{ci}")
        if not any(M.under(root_internal(cell["workspaceRoot"]), root_internal(w)) for w in scope["workspaceRoots"]):
            faults.append(f"ENUMERATION_CELL_ROOT_OUTSIDE_SCOPE:{ci}")
        candidate_only = cell["capabilityId"] in ("clones-near", "clones-cross-tsjs")
        if len(cell["programBindings"]) > 128:
            faults.append("ENUMERATION_PLAN_PROGRAM_BINDINGS_OVERFLOW")
        for b in cell["programBindings"]:
            po = b["ordinal"]
            avail = b["universe"] is not None
            if avail:
                if b["enumerator"]["status"] != "selected":
                    faults.append("ENUMERATION_BINDING_ENUMERATOR")
                if b["nativeContextDigest"] not in plan["nativeContextDigests"]:
                    faults.append("ENUMERATION_BINDING_CONTEXT_NOT_IN_PLAN")
                bound = bound_by_hex.get(b["universe"])
                if bound is None or bound["universe"]["nativeContextId"] != "sha256:" + str(b["nativeContextDigest"]):
                    faults.append("ENUMERATION_BINDING_UNIVERSE_NOT_BOUND_TO_SELECTED_CONTEXT")
                    continue
                want_dom = POLICY_UNIVERSE_MAP[LANGUAGE_MODES[cell["languageMode"]]]
                if bound["domain"] != want_dom:
                    faults.append(f"ENUMERATION_BINDING_UNIVERSE_DOMAIN:{ci}")
                if bound["domain"] == "native.semantic-universe.typescript.v2" and bound["universe"]["languageMode"] != cell["languageMode"]:
                    faults.append(f"ENUMERATION_BINDING_LANGUAGE_MODE:{ci}")
            else:
                if b["nativeContextDigest"] is not None and b["nativeContextDigest"] not in plan["nativeContextDigests"]:
                    faults.append("ENUMERATION_BINDING_CONTEXT_NOT_IN_PLAN")
                if cell["required"] and b["enumerator"]["status"] == "unselected":
                    faults.append("ENUMERATION_PLAN_REQUIRED_UNSELECTED_ENUMERATOR")
                if b.get("deficiency") is None:
                    faults.append("ENUMERATION_BINDING_CAUSE")
            if b["enumerator"]["status"] == "selected":
                c = closures.get(b["enumerator"]["closureId"])
                if b["enumerator"]["closureId"] not in semantic or c is None or c["kind"] != "provider":
                    faults.append("ENUMERATION_BINDING_ENUMERATOR_NOT_IN_PLAN")
            if candidate_only:
                if avail and "candidateSourcePaths" not in b:
                    faults.append("ENUMERATION_CANDIDATE_SOURCE_PATHS")
            elif "candidateSourcePaths" in b:
                faults.append("ENUMERATION_CANDIDATE_SOURCE_PATHS")
            # host-derived extents
            fpaths = file_extent(membership_rec, scope, cell["workspaceRoot"])
            derived = {}
            if "file" in cell["kinds"]:
                derived["file"] = fpaths
            if "package" in cell["kinds"]:
                named, failed = named_manifests(inv_bytes, fpaths)
                derived["package"] = sorted({n["path"] for n in named} | set(failed), key=lambda p: K.C(p))
            if "symbol" in cell["kinds"]:
                if avail:
                    derived["symbol"] = symbol_extent(bound_by_hex[b["universe"]], fpaths, membership_rec)
                else:
                    derived["symbol"] = [p for p in fpaths if M.family_of(p) != "none"]
            got = {e["kind"]: e["paths"] for e in b["extents"]}
            if set(got) != set(cell["kinds"]):
                faults.append(f"ENUMERATION_INVENTORY_KIND_EXTENT_MISMATCH:{ci}:{po}")
            for k, paths in derived.items():
                if got.get(k) != paths:
                    faults.append(f"ENUMERATION_BINDING_EXTENT_MISMATCH:{ci}:{po}:{k}")
            index["extents"][(ci, po)] = derived
    # inventories: exactly one per (cell, program, kind)
    expected = {(ci, b["ordinal"], k) for ci, c in enumerate(enum_plan["cells"]) for b in c["programBindings"] for k in c["kinds"]}
    param_digest = K.raw_digest(enum_plan)
    seen = {}
    for digest, inv in inventories:
        ri = KIT.admit(inv, INV_DOC, "#")
        if not ri["ok"]:
            faults.append(f"ENUMERATION_INVENTORY_SCHEMA:{ri['stock'][:1]}{ri['order'][:1]}")
            continue
        if K.raw_digest(inv) != digest:
            faults.append("EXECUTION_INPUTS_REF_MISMATCH:inventory")
        loc = (inv["cellOrdinal"], inv["programOrdinal"], inv["kind"])
        if inv["planId"] != plan_id or inv["parameterDigest"] != param_digest:
            faults.append("ENUMERATION_INVENTORY_LOCATOR_JOIN")
        if loc not in expected:
            faults.append("ENUMERATION_INVENTORY_ORDINAL_UNBOUND")
            continue
        if loc in seen:
            faults.append("ENUMERATION_INVENTORY_DUPLICATE")
        seen[loc] = (digest, inv)
        ext = index["extents"].get((loc[0], loc[1]), {}).get(inv["kind"], [])
        if not set(inv["examinedPaths"]) <= set(ext):
            faults.append("ENUMERATION_INVENTORY_EXAMINED_OUTSIDE_EXTENT")
        for row in inv["rows"]:
            if row["path"] not in ext and not (inv["kind"] == "package" and row["path"] in ext):
                faults.append("ENUMERATION_INVENTORY_EXTERNAL_PATH")
            if row["kind"] != inv["kind"]:
                faults.append("ENUMERATION_INVENTORY_ROW_KIND")
            if inv["kind"] == "file":
                if not (row["nativeSubjectId"] == row["path"] == row["qualifiedName"]):
                    faults.append("ENUMERATION_INVENTORY_FILE_ROW")
                if row["subjectLanguage"] != subject_language(row["path"]):
                    faults.append("ENUMERATION_INVENTORY_SUBJECT_LANGUAGE")
            if inv["kind"] == "package":
                if row["nativeSubjectId"] != row["qualifiedName"]:
                    faults.append("ENUMERATION_PACKAGE_NAME")
                if row["subjectLanguage"] != ("json" if row["path"].endswith(".json") else "toml"):
                    faults.append("ENUMERATION_INVENTORY_SUBJECT_LANGUAGE")
        if inv["state"] == "complete":
            if inv["kind"] == "file":
                if set(inv["examinedPaths"]) != set(ext) or {r["path"] for r in inv["rows"]} != set(ext):
                    faults.append("ENUMERATION_INVENTORY_FILE_TOTALITY")
            elif inv["kind"] == "symbol":
                if set(inv["examinedPaths"]) != set(ext):
                    faults.append("ENUMERATION_INVENTORY_SYMBOL_EXTENT")
            else:
                named, failed = named_manifests(inv_bytes, ext)
                if failed:
                    faults.append("ENUMERATION_PACKAGE_PARSE")
                if {(n["path"], n["name"]) for n in named} != {(r["path"], r["nativeSubjectId"]) for r in inv["rows"]}:
                    faults.append("ENUMERATION_PACKAGE_TOTALITY")
    missing = expected - set(seen)
    for m in sorted(missing):
        faults.append(f"ENUMERATION_INVENTORY_MISSING_RECORD:{m}")
    index["inventories"] = seen
    return faults, index


def subject_record(universe, row):
    rec = {"schemaVersion": 3, "universe": universe, "kind": row["kind"], "nativeSubjectId": row["nativeSubjectId"]}
    if row["kind"] == "package":
        rec["packageManifestPath"] = row["path"]
    return rec

"""ExecutionInputsV1 derivation and admission (execution-inputs-contract.v1 s1-s7; composition s9.6 bridge).

Derivation is used twice: by the synthetic host capture that authors the claimed record, and by closure/replay,
which re-derives every derived field from retained owner records and compares. Neither reads a claimed state.
"""
import canonical as K
import schemas
from enumeration import cell_state, MATRIX

KIT = schemas.kit()
ID = "foundation/identity-schemas.v3.json"
EXEC_REGISTRY = set(KIT.doc(ID)["x-opensip-evaluator-deficiency-registry"]["sources"]["execution"])
CAUSES = KIT.doc("native/native-evidence.schemas.v2.json")["x-opensip-deficiency-cause-registry"]["deficiencies"]
CAPS = {c["id"]: c for c in MATRIX["capabilities"]}


def cset(items):
    uniq = {K.C(x): x for x in items}
    return [uniq[k] for k in sorted(uniq)]


def matrix_pair(capability, mode):
    cell = cell_state(capability, mode)
    d = cell["deficiency"]
    row = CAUSES.get(d, {})
    cause = row.get("allowedCauses", [None])[0] if row.get("nativeCause") == "required" else None
    return d, cause


def views_of_binding(binding, views, scopes):
    """Views returned by this binding's provider whose scopes all have sourceUniverse == binding U."""
    if binding["universe"] is None or binding["enumerator"]["status"] != "selected":
        return []
    out = []
    for vid, v in sorted(views.items()):
        if v["producerClosure"] != binding["enumerator"]["closureId"]:
            continue
        if v["scopeIds"] and all(scopes[s]["sourceUniverse"] == binding["universe"] for s in v["scopeIds"]):
            out.append(vid)
    return out


def expected_subjects(relation_row_kind, extents, inventories_by_kind):
    if relation_row_kind == "source-path":
        return set(extents.get("file", []))
    if relation_row_kind == "package-name":
        inv = inventories_by_kind.get("package")
        return {r["nativeSubjectId"] for r in inv["rows"]} if inv else set()
    inv = inventories_by_kind.get("symbol")
    return {r["nativeSubjectId"] for r in inv["rows"]} if inv else set()


def derive_accounts(ci, cell, binding, views, scopes, coverages, extents, inventories_by_kind, vcs_kind, relation_registry):
    accounts = []
    bviews = views_of_binding(binding, views, scopes)
    for rel, rung in CAPS[cell["capabilityId"]]["relations"]:
        st = cell_state(cell["capabilityId"], cell["languageMode"])["state"]
        if rel == "vcs-change" and vcs_kind == "none":
            app = "inapplicable-vcs"
        elif st == "UNSUPPORTED-TYPED":
            app = "unsupported-typed"
        elif binding["enumerator"]["status"] == "unselected":
            app = "unavailable-unselected"
        elif binding["universe"] is None:
            app = "unavailable-null-universe"
        else:
            app = "supported-available"
        acc = {"cellOrdinal": ci, "programOrdinal": binding["ordinal"], "relation": rel, "resolution": rung,
               "sourceUniverse": binding["universe"], "targetUniverse": binding["universe"], "applicability": app, "coverageIds": []}
        internal = {"capabilityId": cell["capabilityId"], "records": [], "state": None, "deficiency": None, "nativeCause": None,
                    "censusMissing": [], "scopeIds": []}
        if app == "supported-available":
            recs = []
            covered = set()
            for vid in bviews:
                for cid in views[vid]["coverageIds"]:
                    cov, payload = coverages[cid]
                    k = payload["key"]
                    if k["relation"] == rel and k["resolution"] == rung and k["sourceUniverse"] == binding["universe"]:
                        recs.append((cid.split(":", 1)[1], payload["entry"]["deficiency"], payload["entry"]["nativeCause"], payload["entry"]["coverage"]))
                        covered |= set(scopes[cov["scopeId"]]["subjects"])
                        internal["scopeIds"].append(cov["scopeId"])
            recs = sorted(set(recs))
            acc["coverageIds"] = [r[0] for r in recs]
            internal["records"] = [{"coverage": r[0], "deficiency": r[1], "nativeCause": r[2], "coverage_state": r[3]} for r in recs]
            missing = expected_subjects(relation_registry[rel]["subjectKind"], extents, inventories_by_kind) - covered
            internal["censusMissing"] = sorted(missing)
            complete = bool(recs) and all(r[3] == "complete" for r in recs) and not missing
            internal["state"] = "complete" if complete else "incomplete"
            if not complete:
                carrier = next(((r[1], r[2]) for r in recs if r[1] is not None), (None, None))
                internal["deficiency"], internal["nativeCause"] = carrier
        elif app == "unsupported-typed":
            internal["state"] = "unsupported"
            internal["deficiency"], internal["nativeCause"] = matrix_pair(cell["capabilityId"], cell["languageMode"])
        elif app in ("unavailable-unselected", "unavailable-null-universe"):
            internal["state"] = "unavailable"
            internal["deficiency"], internal["nativeCause"] = binding.get("deficiency"), binding.get("nativeCause")
        else:
            internal["state"] = "inapplicable"
        accounts.append((acc, internal))
    return accounts, bviews


def derive_cell(ci, cell, binding, views, scopes, coverages, extents, inventories_by_kind, inv_digest_by_kind, candidate, vcs_kind, relreg, stage_ordinal):
    accounts, bviews = derive_accounts(ci, cell, binding, views, scopes, coverages, extents, inventories_by_kind, vcs_kind, relreg)
    sources = []
    unavailable = binding["enumerator"]["status"] == "unselected" or binding["universe"] is None
    if unavailable:
        sources.append({"source": "binding", "deficiency": binding.get("deficiency"), "nativeCause": binding.get("nativeCause"), "inputRefs": []})
    inv_digests = sorted(inv_digest_by_kind.values(), key=lambda h: K.C(h))
    for h in inv_digests:
        inv = next(i for k, i in inventories_by_kind.items() if inv_digest_by_kind[k] == h)
        if inv["state"] != "complete":
            sources.append({"source": "inventory", "deficiency": inv["deficiency"], "nativeCause": inv["nativeCause"],
                            "inputRefs": [{"domain": "subject-inventory", "digest": h}], "state": inv["state"]})
    candidate_owed = cell["capabilityId"] in ("clones-near", "clones-cross-tsjs") and not unavailable
    cand_digest = None
    if candidate_owed:
        if candidate is not None:
            cand_digest, env = candidate
            if env["state"] != "complete":
                sources.append({"source": "candidate", "deficiency": env["deficiency"], "nativeCause": env["nativeCause"],
                                "inputRefs": [{"domain": "candidate-producer-result", "digest": cand_digest}]})
        else:
            sources.append({"source": "candidate", "deficiency": None, "nativeCause": None, "inputRefs": [], "absent": True})
    for acc, internal in accounts:
        if internal["state"] == "incomplete":
            if internal["records"]:
                for r in internal["records"]:
                    sources.append({"source": "coverage", "relation": acc["relation"], "resolution": acc["resolution"],
                                    "deficiency": r["deficiency"], "nativeCause": r["nativeCause"],
                                    "inputRefs": [{"domain": "coverage", "digest": r["coverage"]}]})
            else:
                sources.append({"source": "account", "relation": acc["relation"], "resolution": acc["resolution"],
                                "deficiency": None, "nativeCause": None,
                                "inputRefs": [{"domain": "coverage", "digest": c} for c in acc["coverageIds"]]})
        elif internal["state"] == "unsupported":
            sources.append({"source": "account-unsupported", "relation": acc["relation"], "resolution": acc["resolution"],
                            "deficiency": internal["deficiency"], "nativeCause": internal["nativeCause"], "inputRefs": []})
        elif internal["state"] == "unavailable" and not unavailable:
            sources.append({"source": "account-unavailable", "relation": acc["relation"], "resolution": acc["resolution"],
                            "deficiency": internal["deficiency"], "nativeCause": internal["nativeCause"], "inputRefs": []})
    if unavailable:
        state = "unavailable"
    elif candidate_owed and (candidate is None or candidate[1]["state"] == "unavailable"):
        state = "unavailable"
    elif any(s["source"] == "inventory" for s in sources) or any(i["state"] == "incomplete" for _, i in accounts) or \
            (candidate_owed and candidate is not None and candidate[1]["state"] == "partial"):
        state = "partial"
    else:
        state = "complete"
    failing = [s for s in sources if s["source"] != "account-unsupported"] if state != "complete" else []
    carrier = next(((s["deficiency"], s["nativeCause"]) for s in failing + [s for s in sources if s["source"] == "account-unsupported"]
                    if s["deficiency"] is not None), (None, None)) if state != "complete" else (None, None)
    outcome = {"cellOrdinal": ci, "programOrdinal": binding["ordinal"], "capabilityId": cell["capabilityId"],
               "languageMode": cell["languageMode"], "workspaceRoot": cell["workspaceRoot"], "required": cell["required"],
               "kinds": sorted(cell["kinds"], key=lambda k: K.C(k)), "universe": binding["universe"],
               "enumeratorStatus": binding["enumerator"]["status"],
               "enumeratorClosure": binding["enumerator"].get("closureId"),
               "state": state, "deficiency": carrier[0], "nativeCause": carrier[1],
               "stageOrdinal": stage_ordinal if not unavailable else None,
               "stageOrdinalNullReason": None if not unavailable else ("optional-unselected" if binding["enumerator"]["status"] == "unselected" else "unavailable-binding"),
               "inventoryDigests": inv_digests,
               "viewDigests": sorted([v.split(":", 1)[1] for v in bviews], key=lambda h: K.C(h)),
               "candidateResultDigest": cand_digest}
    required_rows = []
    if cell["required"]:
        for s in sources:
            if s.get("absent"):
                continue
            required_rows.append({"cellOrdinal": ci, "programOrdinal": binding["ordinal"], "capabilityId": cell["capabilityId"],
                                  "relation": s.get("relation"), "resolution": s.get("resolution"), "source": s["source"],
                                  "deficiency": s["deficiency"], "nativeCause": s["nativeCause"],
                                  "universe": binding["universe"], "inputRefs": cset(s["inputRefs"])})
    return outcome, accounts, required_rows


def bridge(required_rows, xi_ref):
    items = []
    for row in required_rows:
        d = row["deficiency"]
        if d in EXEC_REGISTRY:
            cause = d
        elif d is None or d == "source-syntax-invalid":
            cause = "required-cell-unsatisfied"
        else:
            raise K.AdmissionError("EVALUATOR_EXECUTION_CAUSE_UNREGISTERED", str(d))
        items.append({"source": "execution", "cause": cause, "subjectId": None, "predicateId": None,
                      "inputRefs": cset([xi_ref] + row["inputRefs"]), "evidenceKind": None,
                      "nativeCause": row["nativeCause"], "universe": row["universe"]})
    return cset(items)


def derive_all(plan, enum_plan, enum_index, views, scopes, coverages, candidates, vcs_kind, relreg, stage_for_binding):
    outcomes, accounts, required_rows, internal_accounts = [], [], [], []
    for ci, cell in enumerate(enum_plan["cells"]):
        for b in cell["programBindings"]:
            invs = {k: enum_index["inventories"][(ci, b["ordinal"], k)][1] for k in cell["kinds"] if (ci, b["ordinal"], k) in enum_index["inventories"]}
            digs = {k: enum_index["inventories"][(ci, b["ordinal"], k)][0] for k in invs}
            extents = enum_index["extents"].get((ci, b["ordinal"]), {})
            cand = candidates.get((ci, b["ordinal"]))
            o, accs, rows = derive_cell(ci, cell, b, views, scopes, coverages, extents, invs, digs, cand, vcs_kind, relreg,
                                        stage_for_binding.get((ci, b["ordinal"])))
            o["ordinal"] = len(outcomes)
            outcomes.append(o)
            accounts += [a for a, _ in accs]
            internal_accounts += [dict(i, **{"cellOrdinal": ci, "programOrdinal": b["ordinal"], "relation": a["relation"], "resolution": a["resolution"]}) for a, i in accs]
            required_rows += rows
    return outcomes, accounts, required_rows, internal_accounts


def selected_refs(receipts, views, plan, outcomes, host_derived_extra):
    refs = []
    for r in receipts:
        if r["state"] == "complete":
            refs += r["outputRefs"]
    for ref in list(refs):
        if ref["domain"] == "view":
            for cid in views["view2:" + ref["digest"]]["coverageIds"]:
                refs.append({"domain": "coverage", "digest": cid.split(":", 1)[1]})
    for o in outcomes:
        refs += [{"domain": "subject-inventory", "digest": d} for d in o["inventoryDigests"]]
        if o["candidateResultDigest"]:
            refs.append({"domain": "candidate-producer-result", "digest": o["candidateResultDigest"]})
    refs += [{"domain": "import", "digest": i.split(":", 1)[1]} for i in plan["importIds"]]
    refs += host_derived_extra
    return cset(refs)


def host_derived_refs(outcomes, host_derived_extra):
    refs = []
    for o in outcomes:
        refs += [{"domain": "subject-inventory", "digest": d} for d in o["inventoryDigests"]]
        if o["candidateResultDigest"]:
            refs.append({"domain": "candidate-producer-result", "digest": o["candidateResultDigest"]})
    return cset(refs + host_derived_extra)


def admit_execution_inputs(claimed, derived, plan, plan_id, exec_plan, exec_plan_id, enum_plan, closures, stage_specs):
    faults = []
    r = KIT.admit(claimed, "foundation/execution-inputs.schema.v1.json", "#")
    if not r["ok"]:
        return [f"EXECUTION_INPUTS_SCHEMA:{r['stock'][:1]}{r['order'][:1]}{r['typed']}"]
    if claimed["planId"] != plan_id:
        faults.append("EXECUTION_INPUTS_PLAN_JOIN")
    if claimed["executionPlanId"] != exec_plan_id:
        faults.append("EXECUTION_INPUTS_EXECUTION_PLAN_JOIN")
    if claimed["enumerationPlanDigest"] != K.raw_digest(enum_plan):
        faults.append("EXECUTION_INPUTS_ENUMERATION_DIGEST")
    if claimed["analysisSpecDigest"] != plan["analysisSpecDigest"]:
        faults.append("EXECUTION_INPUTS_PLAN_JOIN:analysisSpecDigest")
    ev = closures.get(claimed["evaluatorClosure"])
    if claimed["evaluatorClosure"] not in plan["semanticClosures"] or ev is None or ev["kind"] != "evaluator":
        faults.append("EXECUTION_INPUTS_EVALUATOR_CLOSURE")
    receipts = claimed["hostCapture"]["stageReceipts"]
    if [x["ordinal"] for x in receipts] != [s["ordinal"] for s in exec_plan["stages"]]:
        faults.append("EXECUTION_INPUTS_RECEIPT_TOTALITY")
    for rec, stage in zip(receipts, exec_plan["stages"]):
        spec = stage_specs.get(stage["stageSpecDigest"])
        if rec["stageSpecDigest"] != stage["stageSpecDigest"] or spec is None:
            faults.append("EXECUTION_INPUTS_STAGE_ORDINAL")
            continue
        if rec["producerClosure"] != spec["producerClosure"]:
            faults.append("EXECUTION_INPUTS_STAGE_PRODUCER")
        if sorted(rec["outputDomains"]) != sorted(stage["outputDomains"]):
            faults.append("EXECUTION_INPUTS_STAGE_ORDINAL:outputDomains")
        if any(o["domain"] not in rec["outputDomains"] for o in rec["outputRefs"]):
            faults.append("EXECUTION_INPUTS_STAGE_ORDINAL:outputRefs")
    if claimed["cellOutcomes"] != derived["outcomes"]:
        faults.append("EXECUTION_INPUTS_OUTCOME_DERIVE")
    if claimed["nativeCoverageAccounts"] != derived["accounts"] and \
            sorted(claimed["nativeCoverageAccounts"], key=K.C) != sorted(derived["accounts"], key=K.C):
        faults.append("EXECUTION_INPUTS_COVERAGE_DERIVE")
    if claimed["selectedRefs"] != derived["selectedRefs"]:
        faults.append("EXECUTION_INPUTS_SELECTED_COVER")
    if claimed["hostCapture"]["hostDerivedRefs"] != derived["hostDerivedRefs"]:
        faults.append("EXECUTION_INPUTS_HOST_DERIVED")
    if claimed["candidateResultRefs"] != cset([o["candidateResultDigest"] for o in derived["outcomes"] if o["candidateResultDigest"]]):
        faults.append("EXECUTION_INPUTS_CANDIDATE_BIND")
    for row in derived["requiredRows"]:
        if row["deficiency"] is not None and row["deficiency"] not in EXEC_REGISTRY and row["deficiency"] != "source-syntax-invalid":
            faults.append("EVALUATOR_EXECUTION_CAUSE_UNREGISTERED")
    return faults

"""Independent evaluator3: population, atom evaluation (native source endpoint and imported runtime/history atoms),
strong-Kleene composition, witnesses, predicate proofs, findings, waivers, rule results, execution deficiencies,
verdict, proof bundle, semantic evidence, seal, Run and policy derivation.

Sources: identity-and-evidence s4, enumeration-contract s1-s5, atom-evaluation-contract s1-s7,
evaluator-composition-contract.v3 s2-s5 and s9, evaluator-projection-registry.v1.json, native s4.6 (sufficiency_v2),
glob-pattern-contract.v1. Reads only admitted retained inputs; it never reads claimed findings/witnesses/verdict.

Implemented atom planes: native endpoint=source (all native relations), imported runtime-observation and
history-change at endpoint=source. endpoint=target (incoming) atoms are REFUSED here as not implemented by this
reconstruction ('cb24.ATOM_ENDPOINT_TARGET_NOT_RECONSTRUCTED'); no claimed Run uses one.
"""
