import canonical as K
import schemas
from globmatch import glob_match, rule_enumeration_selects, scope_document_selects
from native_facts import RELS, sufficiency_v2, ladder_ok, ladder_index, RESOLVED
from execinputs import cset, bridge

KIT = schemas.kit()
ID = "foundation/identity-schemas.v3.json"
PDOC2 = "workflows/schemas/policy-document.v2.schema.json"
PROJ = KIT.doc("foundation/evaluator-projection-registry.v1.json")
PROFILE = KIT.doc(ID)["x-opensip-evaluator-profile"]
DEFREG = KIT.doc(ID)["x-opensip-evaluator-deficiency-registry"]
LANGUAGE_MODES = KIT.doc(ID)["x-opensip-digest-domains"]["languageModes"]["map"]
SEV = {"note": 0, "warning": 1, "error": 2}
NONBLOCKING = set(DEFREG["nonBlockingDisclosures"])
ATOM_OPS = {"exists", "none", "count-at-most", "all-covered"}
FAMILY_OF_DOMAIN = {v["universeDomain"]: k for k, v in PROJ["engineFamilies"]["families"].items()}
FAMILY_OF_MODE = {m: k for k, v in PROJ["engineFamilies"]["families"].items() for m in v["languageModes"]}


class EvalRefusal(Exception):
    def __init__(self, key, detail=""):
        super().__init__(f"{key}:{detail}" if detail else key)
        self.key = key


def h_suffix(ident):
    return ident.split(":", 1)[1]


def node_list(pred, addr="p"):
    """Postorder list of (address, node)."""
    out = []
    op = pred["op"]
    if op in ("and", "or"):
        for i, ch in enumerate(pred["operands"]):
            out += node_list(ch, f"{addr}.{i}")
    elif op == "not":
        out += node_list(pred["operand"], f"{addr}.0")
    out.append((addr, pred))
    return out


def children_addrs(pred, addr):
    if pred["op"] in ("and", "or"):
        return [f"{addr}.{i}" for i in range(len(pred["operands"]))]
    if pred["op"] == "not":
        return [f"{addr}.0"]
    return []


def kleene(op, vals):
    if op == "not":
        return {"true": "false", "false": "true"}.get(vals[0], "indeterminate")
    if op == "and":
        if "false" in vals:
            return "false"
        return "true" if all(v == "true" for v in vals) else "indeterminate"
    if "true" in vals:
        return "true"
    return "false" if all(v == "false" for v in vals) else "indeterminate"


class Inputs:
    """Admitted retained evaluation inputs (already joined by closure)."""

    def __init__(self, plan, plan_id, exec_plan_id, evaluator_closure, policy, policy_digest, rule_program, waivers,
                 emission, enum_plan, inventories, views, scopes, coverages, facts, fact_payloads, bound, closures,
                 imports, import_payloads, import_observations, import_scopes, import_flags, exec_inputs,
                 exec_inputs_digest, required_rows, scope_document, snapshot_inventory):
        self.__dict__.update(locals())
        del self.__dict__["self"]


def evaluation_input_refs(inp):
    xi = {"domain": "execution-inputs", "digest": inp.exec_inputs_digest}
    return cset(inp.exec_inputs["selectedRefs"] + [xi]), xi


# ------------------------------------------------------------------ enumeration (composition s2, s9.5)
def rule_enumeration(inp, rule):
    if not rule["enabled"]:
        return {"state": "disabled", "inventoryRefs": [], "selectedSubjectIds": [], "unresolvedSubjectIds": [],
                "incompleteInventoryRefs": []}, [], {}
    token = rule["subjectEnumeration"]["universe"]
    if token not in PROFILE["policyUniverseMap"]:
        raise EvalRefusal("EVALUATOR_POLICY_UNIVERSE_TOKEN_UNKNOWN", token)
    domain_token = token
    kind_req = rule["subjectEnumeration"]["subjectKind"]
    primary = "symbol" if kind_req == "export" else kind_req
    defs, refs, incomplete = [], [], []
    subjects = {}
    unresolved = set()
    for ci, cell in enumerate(inp.enum_plan["cells"]):
        if LANGUAGE_MODES[cell["languageMode"]] != domain_token:
            continue
        for b in cell["programBindings"]:
            key = (ci, b["ordinal"], primary)
            if key not in inp.inventories:
                continue
            digest, inv = inp.inventories[key]
            ref = {"domain": "subject-inventory", "digest": digest}
            refs.append(ref)
            if inv["state"] != "complete":
                incomplete.append(ref)
                defs.append({"source": "enumeration", "cause": "incomplete-inventory", "subjectId": None, "predicateId": None,
                             "inputRefs": [ref], "evidenceKind": None, "nativeCause": inv["nativeCause"], "universe": None})
                if inv["deficiency"] == "source-syntax-invalid":
                    defs.append({"source": "enumeration", "cause": "source-syntax-invalid", "subjectId": None, "predicateId": None,
                                 "inputRefs": [ref], "evidenceKind": None, "nativeCause": None, "universe": None})
            for row in inv["rows"]:
                if not rule_enumeration_selects(rule["subjectEnumeration"].get("include"), rule["subjectEnumeration"].get("exclude"), row["path"]):
                    continue
                if inp.scope_document is not None and not scope_document_selects(inp.scope_document, row["path"]):
                    continue
                rec = {"schemaVersion": 3, "universe": b["universe"], "kind": row["kind"], "nativeSubjectId": row["nativeSubjectId"]}
                if row["kind"] == "package":
                    rec["packageManifestPath"] = row["path"]
                sid = K.identifier("evaluation-subject", rec)
                if kind_req == "export":
                    if row.get("exported") == "not-exported":
                        continue
                    if row.get("exported") == "unknown":
                        unresolved.add(sid)
                        defs.append({"source": "enumeration", "cause": "unknown-export-membership", "subjectId": sid, "predicateId": None,
                                     "inputRefs": [ref], "evidenceKind": None, "nativeCause": None, "universe": None})
                        continue
                attrs = {k: row.get(k) for k in ("path", "qualifiedName", "subjectLanguage", "exported", "signatureTokens", "projections")}
                if sid in subjects and subjects[sid]["attrs"] != attrs:
                    raise EvalRefusal("EVALUATION.FINDING_JOIN_REFUSED", "attribution-conflict")
                subjects.setdefault(sid, {"record": rec, "row": row, "attrs": attrs, "inventoryRef": ref, "cell": cell, "binding": b})
    if not refs:
        defs.append({"source": "enumeration", "cause": "no-covering-program", "subjectId": None, "predicateId": None,
                     "inputRefs": [], "evidenceKind": None, "nativeCause": None, "universe": None})
    enum = {"state": "incomplete" if defs else "complete", "inventoryRefs": cset(refs),
            "selectedSubjectIds": sorted(subjects, key=lambda s: K.C(s)),
            "unresolvedSubjectIds": sorted(unresolved, key=lambda s: K.C(s)), "incompleteInventoryRefs": cset(incomplete)}
    return enum, cset(defs), subjects


# ------------------------------------------------------------------ native atom (endpoint=source)
def fold_entries(entries):
    """Fold several ViewEntryV3 of one dependency relation (atom contract s4 deterministic view, step 3)."""
    rank_cov = {"complete": 0, "unknown": 1}
    rank_rc = {"complete": 0, "not-applicable": 0, "partial": 1, "incomplete": 2, "not-attempted": 3}
    rank_cw = {"closed": 0, "open": 1, "unknown": 2}
    cur = dict(entries[0])
    kinds = list(cur["derivationKinds"])
    carrier = next(((e["deficiency"], e["nativeCause"]) for e in entries if e["deficiency"] is not None), (None, None))
    for e in entries[1:]:
        if rank_cov[e["coverage"]] > rank_cov[cur["coverage"]]:
            cur["coverage"] = e["coverage"]
        cur["confidenceMillionths"] = min(cur["confidenceMillionths"], e["confidenceMillionths"])
        if rank_rc[e["resolutionCompleteness"]["state"]] > rank_rc[cur["resolutionCompleteness"]["state"]]:
            cur["resolutionCompleteness"] = e["resolutionCompleteness"]
        if rank_cw[e["closedWorld"]["exportsClosed"]] > rank_cw[cur["closedWorld"]["exportsClosed"]]:
            cur["closedWorld"] = e["closedWorld"]
        for k in e["derivationKinds"]:
            if k not in kinds:
                kinds.append(k)
    cur["derivationKinds"] = kinds
    cur["deficiency"], cur["nativeCause"] = carrier
    return cur


def projection_value(field, rel, fact, payload, subject):
    spec = PROJ["relations"][rel]["filters"].get(field, "forbidden")
    if isinstance(spec, dict):
        spec = spec.get(fact["resolution"], "forbidden")
    if spec == "forbidden":
        raise EvalRefusal("ATOM_FILTER_FIELD_FORBIDDEN", f"{rel}:{field}")
    if spec.startswith("payload."):
        return payload.get(spec[8:])
    if spec == "fact.anchors[0].path":
        return fact["anchors"][0]["path"]
    if spec == "fact.resolution":
        return fact["resolution"]
    if spec == "fact.confidenceMillionths":
        return fact["confidenceMillionths"]
    if spec == "endpoint-universe-domain":
        return subject["domain"]
    if spec.startswith("inventory.kind") or spec.startswith("source-endpoint-kind"):
        return subject["record"]["kind"]
    raise EvalRefusal("cb24.ATOM_FILTER_PROJECTION_NOT_RECONSTRUCTED", spec)


def filter_admission(atom):
    rel = atom["relation"]
    table = PROJ["comparatorTable"]
    for f in atom["filters"]:
        spec = PROJ["relations"][rel]["filters"].get(f["field"], "forbidden")
        if spec == "forbidden" or (isinstance(spec, dict) and spec.get(atom["minResolution"], "forbidden") == "forbidden"):
            raise EvalRefusal("ATOM_FILTER_FIELD_FORBIDDEN", f"{rel}:{f['field']}")
        allowed = table[f["field"]].get(f["cmp"])
        if not allowed:
            raise EvalRefusal("ATOM_FILTER_COMPARATOR_ILLEGAL", f"{f['field']}:{f['cmp']}")
        enum = table[f["field"]].get("enum")
        if f["field"] == "universe":
            enum = PROJ["engineFamilies"]["portableUniverseDomains"]
        if f["field"] == "resolution":
            enum = RELS[rel]["ladder"]
        if enum and f["cmp"] in ("eq", "neq", "in"):
            vals = f["value"] if isinstance(f["value"], list) else [f["value"]]
            if any(v not in enum for v in vals):
                raise EvalRefusal("ATOM_FILTER_ENUM_LITERAL_UNKNOWN", f"{f['field']}:{f['value']}")


def filter_match(f, value):
    cmp, want = f["cmp"], f["value"]
    if value is None:
        return None
    if cmp == "eq":
        return value == want
    if cmp == "neq":
        return value != want
    if cmp == "in":
        return value in want
    if cmp == "prefix":
        return isinstance(value, str) and value.encode().startswith(want.encode())
    if cmp == "glob":
        return isinstance(value, str) and glob_match(want, value)
    if cmp == "gte":
        return value >= want
    if cmp == "lte":
        return value <= want
    return None


def occupies_source(rel, fact, payload, subject):
    row = PROJ["relations"][rel]
    rec = subject["record"]
    if rel == "package":
        return payload.get("packageName") == rec["nativeSubjectId"] and payload.get("manifestPath") == rec.get("packageManifestPath")
    if row["sourceField"] == "anchors[0].path":
        return bool(fact["anchors"]) and fact["anchors"][0]["path"] == rec["nativeSubjectId"]
    return payload.get(row["sourceField"]) == rec["nativeSubjectId"]


def native_atom(inp, atom, subject, EI, sel_views):
    rel, minr = atom["relation"], atom["minResolution"]
    if atom.get("endpoint", "source") != "source":
        raise EvalRefusal("cb24.ATOM_ENDPOINT_TARGET_NOT_RECONSTRUCTED")
    if rel not in RELS or not ladder_ok(rel, minr):
        raise EvalRefusal("ATOM_RELATION_OR_RUNG_UNREGISTERED", f"{rel}@{minr}")
    reg = PROJ["relations"][rel]
    if subject["record"]["kind"] != reg["sourceSubjectKind"]:
        raise EvalRefusal("ATOM_KIND_INCOMPATIBLE", f"{rel}:{subject['record']['kind']}")
    if atom.get("evidence") is not None:
        raise EvalRefusal("ATOM_EVIDENCE_KIND_MISMATCH")
    filter_admission(atom)
    U = subject["record"]["universe"]
    sub_family = FAMILY_OF_DOMAIN.get(subject["domain"])
    cap = PROJ["capabilityForRelation"][rel]
    owed = [(cell, b) for cell in inp.enum_plan["cells"] if cell["capabilityId"] == cap for b in cell["programBindings"]]
    causes, native_defs, scope_ids, coverage_ids = [], [], [], []
    complete = True

    def cause(code, universe=None, native_cause=None):
        c = {"code": code, "evidenceKind": None, "nativeCause": native_cause}
        if universe is not None:
            c["universe"] = universe
        causes.append(c)

    for cell, b in owed:
        if b["universe"] is None:
            bfam = FAMILY_OF_MODE.get(cell["languageMode"])
            if not (bfam is None or sub_family is None or bfam == sub_family):
                cause("cross-family-edge-not-owed")
    result_done = False
    if not owed:
        cause("missing-relation-coverage")
        complete, result_done = False, True
    if not result_done and not any(b["universe"] == U for _, b in owed):
        cause("selector-unbound")
        complete, result_done = False, True
    if not result_done:
        containing = []
        for vid in sel_views:
            for sid in inp.views[vid]["scopeIds"]:
                s = inp.scopes[sid]
                if s["relation"] == rel and s["resolution"] == minr and s["sourceUniverse"] == U and subject["record"]["nativeSubjectId"] in s["subjects"]:
                    containing.append(sid)
        containing = sorted(set(containing), key=lambda x: K.C(x))
        if not containing:
            cause("uncovered-expected-source-subject", U)
            complete, result_done = False, True
        else:
            scope_ids = containing
            paired = {}
            for vid in sel_views:
                for cid in inp.views[vid]["coverageIds"]:
                    cov, payload = inp.coverages[cid]
                    if cov["scopeId"] in containing:
                        paired.setdefault(cov["scopeId"], set()).add(cid)
            unpaired = [s for s in containing if s not in paired]
            for _ in unpaired:
                cause("scope-without-coverage", U)
            if unpaired or not paired:
                complete, result_done = False, True
            else:
                covs = sorted({c for v in paired.values() for c in v}, key=lambda x: K.C(x))
                for cid in covs:
                    coverage_ids.append(cid)
                    cov, payload = inp.coverages[cid]
                    entry, key = payload["entry"], payload["key"]
                    view = {rel: dict(entry)}
                    deps_first_cause = entry["nativeCause"]
                    for dep in [d for d in _dep_closure(rel)]:
                        dep_entries = []
                        for vid in sel_views:
                            for dcid in inp.views[vid]["coverageIds"]:
                                dcov, dpay = inp.coverages[dcid]
                                dk = dpay["key"]
                                if dk["relation"] == dep["relation"] and dk["resolution"] == dep["minResolution"] and \
                                        dk["sourceUniverse"] == key["sourceUniverse"] and dk["targetUniverse"] == key["targetUniverse"]:
                                    dep_entries.append((dcid, dpay["entry"]))
                        dep_entries = sorted(set((c, K.C(e)) for c, e in dep_entries))
                        if dep_entries:
                            ents = [K.parse_raw(eb) for _, eb in dep_entries]
                            view[dep["relation"]] = fold_entries(ents)
                            if deps_first_cause is None:
                                deps_first_cause = view[dep["relation"]]["nativeCause"]
                    quant = "universal-negative" if minr in RESOLVED else "existential"
                    req = {"relation": rel, "minResolution": minr, "completeness": "complete", "quantifier": quant,
                           "unresolvedEdgePolicy": "forbid", "externalConsumerPolicy": "forbid", "minConfidenceMillionths": 0}
                    s = sufficiency_v2(req, view)
                    if not s["satisfied"]:
                        cause("coverage-unknown", key["sourceUniverse"], deps_first_cause)
                        native_defs.append(s["deficiency"])
                        complete = False
    known, uncertain = [], []
    for vid in sel_views:
        for fid in inp.views[vid]["facts"]:
            f = inp.facts[fid]
            p = inp.fact_payloads[fid]
            if f["relation"] != rel or not ladder_ok(rel, f["resolution"]) or ladder_index(rel, f["resolution"]) < ladder_index(rel, minr):
                continue
            if f["sourceUniverse"] != U or not occupies_source(rel, f, p, subject):
                continue
            verdicts = [filter_match(flt, projection_value(flt["field"], rel, f, p, subject)) for flt in atom["filters"]]
            if all(v is True for v in verdicts):
                known.append(fid)
            elif not any(v is False for v in verdicts):
                uncertain.append(fid)
    known = sorted(set(known), key=lambda x: K.C(x))
    uncertain = sorted(set(uncertain) - set(known), key=lambda x: K.C(x))
    blocking = [c for c in causes if c["code"] not in NONBLOCKING]
    comp_ok = complete and not blocking and not uncertain
    op = atom["op"]
    if op == "exists":
        value = "true" if known else ("false" if comp_ok else "indeterminate")
    elif op == "none":
        value = "false" if known else ("true" if comp_ok else "indeterminate")
    elif op == "count-at-most":
        value = "false" if len(known) > atom["n"] else ("true" if comp_ok else "indeterminate")
    else:
        value = "true" if (complete and not blocking) else "indeterminate"
    return {"value": value, "knownFactIds": known, "uncertainFactIds": uncertain, "knownRows": [], "uncertainRows": [],
            "coverageIds": coverage_ids, "scopeIds": scope_ids, "causes": causes, "nativeDeficiencies": sorted(set(native_defs)),
            "plane": "native"}


def _dep_closure(rel):
    from native_facts import DEPENDS_ON
    seen, queue, out = {rel}, [rel], []
    while queue:
        r = queue.pop(0)
        for d in DEPENDS_ON.get(r, []):
            if d["relation"] not in seen:
                seen.add(d["relation"])
                out.append(d)
                queue.append(d["relation"])
    return out


# ------------------------------------------------------------------ imported atoms (runtime-observation, history-change)
def imported_atom(inp, atom, subject, rule, EI):
    rel = atom["relation"]
    kind = {"runtime-observation": "runtime", "history-change": "history"}.get(rel)
    if kind is None:
        raise EvalRefusal("cb24.IMPORTED_ATOM_RELATION_NOT_RECONSTRUCTED", rel)
    if atom.get("evidence") != kind:
        raise EvalRefusal("ATOM_EVIDENCE_KIND_MISMATCH")
    if not any(e["kind"] == kind for e in rule["evidenceUse"]):
        raise EvalRefusal("cb24.IMPORTED_ATOM_UNDECLARED_EVIDENCE_USE", kind)
    path = subject["row"]["path"]
    owed = []
    for iid in sorted(inp.plan["importIds"], key=lambda x: K.C(x)):
        wrapper = inp.imports[iid]
        if wrapper["kind"] != kind:
            continue
        scope = inp.import_scopes[iid]
        from membership import in_foundation_scope
        if in_foundation_scope(path, scope):
            owed.append(iid)
    causes, known_rows, uncertain_rows = [], [], []
    complete = True
    if not owed:
        causes.append({"code": "zero-owed-wrappers", "evidenceKind": kind, "nativeCause": None})
        causes.append({"code": "evidence-kind-unavailable", "evidenceKind": kind, "nativeCause": None})
        complete = False
    for iid in owed:
        wrapper, payload, obs = inp.imports[iid], inp.import_payloads[iid], inp.import_observations[iid]
        flags = inp.import_flags[iid]
        if not flags["consumable"]:
            causes.append({"code": "import-unmapped-only", "evidenceKind": kind, "nativeCause": None, "importId": iid})
            complete = False
            continue
        if wrapper["completeness"] != "complete":
            causes.append({"code": "wrapper-partial", "evidenceKind": kind, "nativeCause": None, "importId": iid})
            complete = False
        if kind == "runtime":
            if obs["window"] != payload["observationWindow"] or obs["population"] != payload["observedPopulation"]:
                raise EvalRefusal("ATOM_IMPORT_OBSERVATION_PAYLOAD_JOIN")
            if payload["observedPopulation"] == "unknown":
                causes.append({"code": "observation-window-insufficient", "evidenceKind": kind, "nativeCause": None, "importId": iid})
                complete = False
            rows = [(i, r) for i, r in enumerate(payload["subjects"]) if r["path"] == path and "symbol" not in r]
            if len(rows) > 1:
                raise EvalRefusal("RUNTIME_SUBJECT_DUPLICATE_KEY")
            polarity_filter = [f for f in atom["filters"] if f["field"] == "observability"]
            if not rows:
                causes.append({"code": "no-consumable-row", "evidenceKind": kind, "nativeCause": None, "importId": iid})
                complete = False
            for i, r in rows:
                addr = {"importId": iid, "selector": "runtime-subject", "ordinal": i}
                if r["observability"] in ("observed-hit", "observable-unhit"):
                    ok = all(filter_match(f, r["observability"]) for f in polarity_filter)
                    if ok:
                        known_rows.append(addr)
                else:
                    uncertain_rows.append(addr)
                    causes.append({"code": "unobservable-subject" if r["observability"] == "unobservable" else "unmapped-subject",
                                   "evidenceKind": kind, "nativeCause": None, "importId": iid})
                    complete = False
        else:
            if obs["revisionRange"]["to"] != payload["revisionRange"]["to"] or obs["revisionRange"]["from"] != payload["revisionRange"]["from"]:
                raise EvalRefusal("ATOM_IMPORT_OBSERVATION_PAYLOAD_JOIN")
            if payload["revisionRange"]["truncated"]:
                causes.append({"code": "history-truncated", "evidenceKind": kind, "nativeCause": None, "importId": iid})
                complete = False
            rows = [(i, r) for i, r in enumerate(payload["subjects"]) if r["path"] == path]
            if payload["collectionScope"] == "listed-paths" and not rows:
                causes.append({"code": "history-outside-collection-scope", "evidenceKind": kind, "nativeCause": None, "importId": iid})
                complete = False
            for i, r in rows:
                known_rows.append({"importId": iid, "selector": "history-subject", "ordinal": i})
    known_rows = cset(known_rows)
    uncertain_rows = cset(uncertain_rows)
    comp_ok = complete and not uncertain_rows
    op = atom["op"]
    if op == "exists":
        value = "true" if known_rows else ("false" if comp_ok else "indeterminate")
    elif op == "none":
        value = "false" if known_rows else ("true" if comp_ok else "indeterminate")
    elif op == "count-at-most":
        value = "false" if len(known_rows) > atom["n"] else ("true" if comp_ok else "indeterminate")
    else:
        value = "true" if comp_ok else "indeterminate"
    return {"value": value, "knownFactIds": [], "uncertainFactIds": [], "knownRows": known_rows, "uncertainRows": uncertain_rows,
            "coverageIds": [], "scopeIds": [], "causes": causes, "nativeDeficiencies": [], "plane": "import"}


# ------------------------------------------------------------------ composition
def atom_deficiencies(res, atom, sid, addr, EI, inp):
    out = []
    plane = res["plane"]
    for c in res["causes"]:
        if c["code"] not in set(DEFREG["sources"][plane]) | NONBLOCKING:
            raise EvalRefusal("EVALUATOR_ATOM_CAUSE_UNREGISTERED", c["code"])
        out.append({"source": plane, "cause": c["code"], "subjectId": sid, "predicateId": addr, "inputRefs": EI,
                    "evidenceKind": atom.get("evidence") if plane == "import" else None, "nativeCause": c["nativeCause"],
                    "universe": c.get("universe")})
    for d in res["nativeDeficiencies"]:
        out.append({"source": "native", "cause": d, "subjectId": sid, "predicateId": addr, "inputRefs": EI,
                    "evidenceKind": None, "nativeCause": None, "universe": None})
    for cid in res["coverageIds"]:
        cov, payload = inp.coverages[cid]
        if payload["entry"]["deficiency"] is not None:
            out.append({"source": "native", "cause": payload["entry"]["deficiency"], "subjectId": sid, "predicateId": addr,
                        "inputRefs": [{"domain": "coverage", "digest": h_suffix(cid)}], "evidenceKind": None,
                        "nativeCause": payload["entry"]["nativeCause"], "universe": payload["key"]["sourceUniverse"]})
    return cset(out)


def is_blocking(d, rule):
    if d["cause"] in NONBLOCKING:
        return False
    if d["source"] == "import":
        return any(e["kind"] == d["evidenceKind"] and e["requirement"] == "required" for e in rule["evidenceUse"])
    return True


def evaluate(inp, blobs_out=None, objects_out=None):
    """Complete proof derivation. blobs_out/objects_out collect retained output preimages."""
    blobs_out = {} if blobs_out is None else blobs_out
    objects_out = {} if objects_out is None else objects_out
    EI, xi = evaluation_input_refs(inp)
    sel_views = sorted(["view2:" + r["digest"] for r in EI if r["domain"] == "view"], key=lambda x: K.C(x))
    policy = inp.policy
    program_digest = K.raw_digest(inp.rule_program)
    bindings = {r["ruleId"]: r for r in inp.emission["rules"]}
    rules = policy["rules"]
    enumerations = {}
    for rule in rules:
        enumerations[rule["ruleId"]] = rule_enumeration(inp, rule)
    # budget preflight
    E = sum(len(inv["rows"]) for _, inv in inp.inventories.values()) + len(inp.inventories)
    F = len({f for v in sel_views for f in inp.views[v]["facts"]})
    I = 0
    for iid in inp.plan["importIds"]:
        p = inp.import_payloads[iid]
        I += len(p.get("subjects", [])) if "subjects" in p else 1
    Kc = len({r["digest"] for r in EI if r["domain"] == "coverage"})
    charge = E
    for rule in rules:
        if not rule["enabled"]:
            continue
        nodes = node_list(rule["emitWhen"])
        A = sum(1 for _, n in nodes if n["op"] in ATOM_OPS)
        charge += len(enumerations[rule["ruleId"]][2]) * (len(nodes) + A * (F + I + Kc))
    exec_defs = bridge(inp.required_rows, xi)
    budget_exhausted = charge > inp.plan["budget"]["limit"]
    predicate_proofs, findings, rule_results = [], [], []
    waived = []
    if budget_exhausted:
        exec_defs = cset(exec_defs + [{"source": "execution", "cause": "work-budget-exhausted", "subjectId": None, "predicateId": None,
                                       "inputRefs": EI, "evidenceKind": None, "nativeCause": None, "universe": None}])
    for rule in sorted(rules, key=lambda r: r["ruleId"].encode()):
        enum, enum_defs, subjects = enumerations[rule["ruleId"]]
        rdefs = list(enum_defs)
        rfindings = []
        root_indeterminate_blocking = False
        if rule["enabled"]:
            for ev in rule["evidenceUse"]:
                kinds = {inp.imports[i]["kind"] for i in inp.plan["importIds"]}
                if ev["requirement"] == "required" and ev["kind"] not in kinds:
                    rdefs.append({"source": "import", "cause": "evidence-kind-unavailable", "subjectId": None, "predicateId": None,
                                  "inputRefs": [], "evidenceKind": ev["kind"], "nativeCause": None, "universe": None})
            if budget_exhausted:
                rdefs.append({"source": "execution", "cause": "work-budget-exhausted", "subjectId": None, "predicateId": None,
                              "inputRefs": [], "evidenceKind": None, "nativeCause": None, "universe": None})
            else:
                for sid in enum["selectedSubjectIds"]:
                    subject = subjects[sid]
                    b = subject["binding"]
                    subject = dict(subject, domain=inp.bound[b["universe"]]["domain"])
                    results = {}
                    for addr, node in node_list(rule["emitWhen"]):
                        op = node["op"]
                        nd = hashlib.sha256(K.C(node)).hexdigest()
                        ppd = {"schemaVersion": 2, "ruleProgramDigest": program_digest, "ruleId": rule["ruleId"], "predicateId": addr,
                               "operation": op, "nodeDigest": nd}
                        ppd_digest = K.raw_digest(ppd)
                        blobs_out[ppd_digest] = K.C(ppd)
                        if op in ATOM_OPS:
                            if node.get("evidence") is not None or node["relation"] in ("runtime-observation", "history-change", "test-execution", "test-result"):
                                res = imported_atom(inp, node, subject, rule, EI)
                            else:
                                res = native_atom(inp, node, subject, EI, sel_views)
                            defs = atom_deficiencies(res, node, sid, addr, EI, inp)
                            witness = {"schemaVersion": 3, "programPredicateDigest": ppd_digest, "matchingFactIds": res["knownFactIds"],
                                       "coverageIds": sorted(res["coverageIds"], key=lambda x: K.C(x)),
                                       "countLimit": node["n"] if op == "count-at-most" else None, "childPredicateIds": [],
                                       "matchingImportRows": res["knownRows"], "uncertainFactIds": res["uncertainFactIds"],
                                       "uncertainImportRows": res["uncertainRows"], "deficiencies": defs,
                                       "kind": "native-atom" if res["plane"] == "native" else "imported-atom"}
                            value = res["value"]
                            refs = EI
                            scope_ids = sorted(res["scopeIds"], key=lambda x: K.C(x))
                            blocking = [d for d in defs if is_blocking(d, rule)] if value == "indeterminate" else []
                            results[addr] = {"value": value, "defs": defs, "facts": set(res["knownFactIds"]), "ufacts": set(res["uncertainFactIds"]),
                                             "rows": res["knownRows"], "urows": res["uncertainRows"], "coverage": set(res["coverageIds"]),
                                             "scopes": set(scope_ids), "blocking": blocking, "refs": refs}
                        else:
                            chs = children_addrs(node, addr)
                            vals = [results[c]["value"] for c in chs]
                            value = kleene(op, vals)
                            defs = cset([d for c in chs for d in results[c]["defs"]])
                            refs = cset([r for c in chs for r in results[c]["refs"]])
                            scope_ids = sorted({s for c in chs for s in results[c]["scopes"]}, key=lambda x: K.C(x))
                            witness = {"schemaVersion": 3, "programPredicateDigest": ppd_digest, "matchingFactIds": [], "coverageIds": [],
                                       "countLimit": None, "childPredicateIds": sorted(chs, key=lambda x: K.C(x)), "matchingImportRows": [],
                                       "uncertainFactIds": [], "uncertainImportRows": [], "deficiencies": defs, "kind": "boolean"}
                            blocking = [d for c in chs if results[c]["value"] == "indeterminate" for d in results[c]["blocking"]] if value == "indeterminate" else []
                            results[addr] = {"value": value, "defs": defs, "facts": set().union(*[results[c]["facts"] for c in chs]),
                                             "ufacts": set().union(*[results[c]["ufacts"] for c in chs]),
                                             "rows": cset([r for c in chs for r in results[c]["rows"]]),
                                             "urows": cset([r for c in chs for r in results[c]["urows"]]),
                                             "coverage": set().union(*[results[c]["coverage"] for c in chs]),
                                             "scopes": set(scope_ids), "blocking": blocking, "refs": refs}
                        wd = K.raw_digest(witness)
                        blobs_out[wd] = K.C(witness)
                        results[addr]["witnessDigest"] = wd
                        predicate_proofs.append({"ruleId": rule["ruleId"], "subjectId": sid, "predicateId": addr, "operation": op,
                                                 "inputRefs": refs, "scopeIds": scope_ids, "value": value, "witnessDigest": wd})
                        if op in ATOM_OPS:
                            rdefs += defs
                    root = results["p"]
                    if root["value"] == "indeterminate" and root["blocking"]:
                        root_indeterminate_blocking = True
                    if root["value"] == "true":
                        f, corr_defs = mint_finding(inp, rule, bindings[rule["ruleId"]], subject, sid, root, EI, enum, blobs_out, objects_out)
                        rdefs += corr_defs
                        rfindings.append(f)
                        findings.append(f)
        fids = sorted({f["findingId"] for f in rfindings}, key=lambda x: K.C(x))
        rwaived = [f["findingId"] for f in rfindings if waiver_matches(inp.waivers, f)]
        waived += rwaived
        gating = rule["enabled"] and rule["gate"] and SEV[rule["severity"]] >= SEV[policy["gateSeverityAtLeast"]]
        if not rule["enabled"]:
            outcome = "disabled"
        elif gating and any(f["findingId"] not in rwaived for f in rfindings):
            outcome = "fail"
        elif gating and (enum["state"] == "incomplete" or enum["unresolvedSubjectIds"] or root_indeterminate_blocking or budget_exhausted):
            outcome = "indeterminate"
        else:
            outcome = "pass"
        rule_results.append({"ruleId": rule["ruleId"], "enumeration": enum, "outcome": outcome, "findingIds": fids,
                             "deficiencies": cset(rdefs) if rule["enabled"] else []})
    predicate_proofs.sort(key=lambda p: (p["ruleId"].encode(), p["subjectId"].encode(), p["predicateId"].encode()))
    finding_ids = sorted({f["findingId"] for f in findings}, key=lambda x: K.C(x))
    if any(r["outcome"] == "fail" for r in rule_results):
        verdict = "fail"
    elif any(r["outcome"] == "indeterminate" for r in rule_results) or exec_defs:
        verdict = "indeterminate"
    else:
        verdict = "pass"
    proof = {"schemaVersion": 3, "planId": inp.plan_id, "executionPlanId": inp.exec_plan_id, "evaluatorClosure": inp.evaluator_closure,
             "ruleProgramDigest": program_digest, "evaluationInputRefs": EI, "predicateProofs": predicate_proofs,
             "findingIds": finding_ids, "verdict": verdict, "evaluationState": "budget-exhausted" if budget_exhausted else "evaluated",
             "ruleResults": rule_results, "waivedFindingIds": sorted(set(waived), key=lambda x: K.C(x)),
             "executionDeficiencies": exec_defs, "executionInputsDigest": inp.exec_inputs_digest}
    proof_id = K.identifier("proof-bundle", proof)
    objects_out[proof_id] = ("proof-bundle", proof)
    view_ids = sorted(sel_views, key=lambda x: K.C(x))
    cov_ids = {c for v in view_ids for c in inp.views[v]["coverageIds"]} | {"coverage2:" + r["digest"] for r in EI if r["domain"] == "coverage"}
    evidence = {"schemaVersion": 3, "planId": inp.plan_id, "viewIds": view_ids, "coverageIds": sorted(cov_ids, key=lambda x: K.C(x)),
                "importIds": sorted(inp.plan["importIds"], key=lambda x: K.C(x)), "findingIds": finding_ids, "proofBundleId": proof_id}
    evidence_id = K.identifier("semantic-evidence", evidence)
    objects_out[evidence_id] = ("semantic-evidence", evidence)
    seal = {"schemaVersion": 3, "planId": inp.plan_id, "executionPlanId": inp.exec_plan_id, "evidenceId": evidence_id,
            "evaluatorClosure": inp.evaluator_closure, "policyDigest": inp.plan["policyDigest"], "proofBundleId": proof_id, "verdict": verdict}
    seal_id = K.identifier("evaluation-seal", seal)
    objects_out[seal_id] = ("evaluation-seal", seal)
    run = {"schemaVersion": 3, "projectId": inp.snapshot_project, "snapshotId": inp.plan["snapshotId"], "planId": inp.plan_id,
           "evidenceId": evidence_id, "evaluationSealId": seal_id, "capabilityManifestId": inp.plan["capabilityManifestId"]}
    run_id = K.identifier("run", run)
    objects_out[run_id] = ("run", run)
    pd = {"schemaVersion": 3, "planId": inp.plan_id, "proofBundleId": proof_id, "policyDigest": inp.plan["policyDigest"],
          "waiverDigest": inp.plan["waiverDigest"], "verdict": verdict}
    pd_id = K.identifier("policy-derivation", pd)
    objects_out[pd_id] = ("policy-derivation", pd)
    return {"proof": proof, "proofId": proof_id, "evidence": evidence, "evidenceId": evidence_id, "seal": seal, "sealId": seal_id,
            "run": run, "runId": run_id, "policyDerivation": pd, "policyDerivationId": pd_id, "findings": findings,
            "budgetCharge": charge, "blobs": blobs_out, "objects": objects_out}


def mint_finding(inp, rule, binding, subject, sid, root, EI, enum, blobs_out, objects_out):
    row = subject["row"]
    defs = []
    kind = row["kind"]
    if kind in ("file", "package"):
        disc = hashlib.sha256(K.C([])).hexdigest()
        reason = None
    else:
        proj = next((p for p in row["projections"] if p["closureId"] == binding["detectorClosure"]), None)
        if proj is None or not proj["signatureTokens"]:
            reason = "projection-unavailable"
        elif enum["state"] != "complete":
            reason = "population-incomplete"
        else:
            reason = None
            disc = hashlib.sha256(K.C(proj["signatureTokens"])).hexdigest()
        if reason:
            defs.append({"source": "correspondence", "cause": reason, "subjectId": sid, "predicateId": "p",
                         "inputRefs": enum["inventoryRefs"], "evidenceKind": None, "nativeCause": None, "universe": None})
    fingerprint = None
    if reason is None:
        desc = {"schemaVersion": 2, "ruleStableId": rule["ruleProgramRef"]["ruleStableId"],
                "detectorSemanticsMajor": rule["ruleProgramRef"]["semanticsMajor"],
                "subjectKey": {"language": row["subjectLanguage"], "kind": kind, "logicalPath": row["path"],
                               "qualifiedName": row["qualifiedName"], "discriminator": disc},
                "relatedSubjectKeys": []}
        fingerprint = K.identifier("finding-fingerprint", desc)
        objects_out[fingerprint] = ("finding-fingerprint", desc)
    message = rule.get("messageCode", rule["ruleId"])
    params = {"schemaVersion": 2, "messageCode": message,
              "parameters": {"ruleId": rule["ruleId"], "subjectPath": row["path"], "qualifiedName": row["qualifiedName"],
                             "subjectKind": kind, "subjectLanguage": row["subjectLanguage"],
                             "matchingFactCount": len(root["facts"]), "matchingImportCount": len(root["rows"])}}
    pdig = K.raw_digest(params)
    blobs_out[pdig] = K.C(params)
    refs = [{"domain": "predicate-witness", "digest": root["witnessDigest"]}]
    refs += [{"domain": "fact", "digest": h_suffix(f)} for f in root["facts"] | root["ufacts"]]
    refs += [{"domain": "coverage", "digest": h_suffix(c)} for c in root["coverage"]]
    refs += [{"domain": "import", "digest": h_suffix(r["importId"])} for r in root["rows"] + root["urows"]]
    refs += [{"domain": "import", "digest": r["digest"]} for r in EI if r["domain"] == "import"]
    finding = {"schemaVersion": 3, "fingerprint": fingerprint,
               "correspondence": {"state": "matched" if fingerprint else "unmatched", "reason": None if fingerprint else reason},
               "ruleClosure": binding["detectorClosure"], "ruleId": rule["ruleId"], "subjectId": sid,
               "subject": {"language": row["subjectLanguage"], "kind": kind, "logicalPath": row["path"], "qualifiedName": row["qualifiedName"]},
               "messageCode": message, "parameterDigest": pdig, "severity": rule["severity"], "evidenceRefs": cset(refs)}
    fid = K.identifier("finding", finding)
    objects_out[fid] = ("finding", finding)
    subj_id = K.identifier("evaluation-subject", subject["record"])
    objects_out[subj_id] = ("evaluation-subject", subject["record"])
    return {"findingId": fid, "finding": finding, "subjectPath": row["path"]}, defs


def waiver_matches(waivers, f):
    for w in waivers["waivers"]:
        t = w["target"]
        if "fingerprint" in t and f["finding"]["fingerprint"] is not None and t["fingerprint"] == f["finding"]["fingerprint"]:
            return True
        if "ruleId" in t and t["ruleId"] == f["finding"]["ruleId"] and t["subjectPath"] == f["subjectPath"]:
            return True
    return False

