FAMILY_OF_DOMAIN = {v["universeDomain"]: k for k, v in PROJ["engineFamilies"]["families"].items()}
FAMILY_OF_MODE = {m: k for k, v in PROJ["engineFamilies"]["families"].items() for m in v["languageModes"]}
U64_MAX = 2 ** 64 - 1
